class Solution {
public:
    int minSkips(vector<int>& dist, int speed, int hoursBefore) {
        int n = dist.size();
        const long long INF = 1e18;
        vector<long long> dp(n + 1, INF);
        dp[0] = 0;

        for (int i = 0; i < n - 1; ++i) {
            int d = dist[i];
            vector<long long> nextDp(n + 1, INF);
            for (int j = 0; j <= n; ++j) {
                if (dp[j] == INF) continue;
                long long noSkip = ((dp[j] + d + speed - 1) / speed) * speed;
                nextDp[j] = min(nextDp[j], noSkip);
                if (j + 1 <= n) {
                    nextDp[j + 1] = min(nextDp[j + 1], dp[j] + d);
                }
            }
            dp = nextDp;
        }

        int lastD = dist.back();
        long long target = (long long)hoursBefore * speed;
        for (int j = 0; j <= n; ++j) {
            if (dp[j] + lastD <= target) return j;
        }
        return -1;
    }
};

import java.util.*;

class Solution {
    public int minSkips(int[] dist, int speed, int hoursBefore) {
        int n = dist.length;
        long INF = (long)1e18;
        long[] dp = new long[n + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;

        for (int i = 0; i < n - 1; ++i) {
            int d = dist[i];
            long[] nextDp = new long[n + 1];
            Arrays.fill(nextDp, INF);
            for (int j = 0; j <= n; ++j) {
                if (dp[j] == INF) continue;
                long noSkip = ((dp[j] + d + speed - 1) / speed) * speed;
                nextDp[j] = Math.min(nextDp[j], noSkip);
                if (j + 1 <= n) {
                    nextDp[j + 1] = Math.min(nextDp[j + 1], dp[j] + d);
                }
            }
            dp = nextDp;
        }

        int lastD = dist[n - 1];
        long target = (long)hoursBefore * speed;
        for (int j = 0; j <= n; ++j) {
            if (dp[j] + lastD <= target) return j;
        }
        return -1;
    }
}

/**
 * @param {number[]} dist
 * @param {number} speed
 * @param {number} hoursBefore
 * @return {number}
 */
var minSkips = function(dist, speed, hoursBefore) {
    const n = dist.length;
    const INF = 1e18;
    const sp = BigInt(speed);
    let dp = Array(n + 1).fill(BigInt(INF));
    dp[0] = 0n;

    for (let i = 0; i < n - 1; ++i) {
        const d = BigInt(dist[i]);
        const nextDp = Array(n + 1).fill(BigInt(INF));
        for (let j = 0; j <= n; ++j) {
            if (dp[j] >= BigInt(INF)) continue;
            const noSkip = ((dp[j] + d + sp - 1n) / sp) * sp;
            if (noSkip < nextDp[j]) nextDp[j] = noSkip;
            if (j + 1 <= n) {
                const withSkip = dp[j] + d;
                if (withSkip < nextDp[j + 1]) nextDp[j + 1] = withSkip;
            }
        }
        dp = nextDp;
    }

    const lastD = BigInt(dist[n - 1]);
    const target = BigInt(hoursBefore) * sp;
    for (let j = 0; j <= n; ++j) {
        if (dp[j] + lastD <= target) return j;
    }
    return -1;
};
